typedef long long ll;

typedef struct {
    int to, rev;
    ll cap;
} Edge;

Edge graph[MAXN][MAXN];
int graph_size[MAXN];
int level[MAXN];
int it[MAXN];
int n;

void add_edge(int from, int to, ll cap) {
    graph[from][graph_size[from]] = (Edge){to, graph_size[to], cap};
    graph[to][graph_size[to]] = (Edge){from, graph_size[from], 0};
    graph_size[from]++;
    graph_size[to]++;
}

int bfs(int s, int t) {
    memset(level, -1, sizeof(level));
    int q[MAXN], front = 0, back = 0;
    level[s] = 0;
    q[back++] = s;
    while (front < back) {
        int v = q[front++];
        for (int i = 0; i < graph_size[v]; i++) {
            Edge e = graph[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q[back++] = e.to;
            }
        }
    }
    return level[t] >= 0;
}

ll dfs(int v, int t, ll f) {
    if (v == t) return f;
    for (int &i = it[v]; i < graph_size[v]; i++) {
        Edge &e = graph[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            ll d = dfs(e.to, t, f < e.cap ? f : e.cap);
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

ll max_flow(int s, int t) {
    ll flow = 0;
    while (bfs(s, t)) {
        memset(it, 0, sizeof(it));
        ll f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
    return flow;
}

