#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define INF 1e100
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    int u, v;
    double cap;
    int next;
} Edge;

static Point *pts = NULL;
static int pcount = 0, pcap = 0;

static Edge *edges = NULL;
static int *head = NULL;
static int edgeCnt = 0, nodeCnt = 0;

static int *levelArr = NULL;
static int *itArr = NULL;
static int *queueArr = NULL;

double dist_pt(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int same_point(Point a, Point b) {
    return fabs(a.x - b.x) < EPS && fabs(a.y - b.y) < EPS;
}

int get_point_id(Point p) {
    for (int i = 0; i < pcount; i++) {
        if (same_point(pts[i], p)) return i;
    }
    if (pcount == pcap) {
        pcap = pcap ? pcap * 2 : 64;
        pts = (Point *)realloc(pts, sizeof(Point) * pcap);
    }
    pts[pcount] = p;
    return pcount++;
}

void init_graph(int n, int maxEdges) {
    nodeCnt = n;
    head = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) head[i] = -1;
    edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
    edgeCnt = 0;
}

void add_edge(int u, int v, double cap) {
    edges[edgeCnt].u = u;
    edges[edgeCnt].v = v;
    edges[edgeCnt].cap = cap;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;

    edges[edgeCnt].u = v;
    edges[edgeCnt].v = u;
    edges[edgeCnt].cap = 0.0;
    edges[edgeCnt].next = head[v];
    head[v] = edgeCnt++;
}

int bfs(int s, int t) {
    for (int i = 0; i < nodeCnt; i++) levelArr[i] = -1;
    int qh = 0, qt = 0;
    queueArr[qt++] = s;
    levelArr[s] = 0;

    while (qh < qt) {
        int u = queueArr[qh++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            if (edges[e].cap > EPS && levelArr[edges[e].v] < 0) {
                levelArr[edges[e].v] = levelArr[u] + 1;
                queueArr[qt++] = edges[e].v;
            }
        }
    }
    return levelArr[t] >= 0;
}

double dfs(int u, int t, double f) {
    if (u == t) return f;
    for (int *pe = &itArr[u]; *pe != -1; *pe = edges[*pe].next) {
        int e = *pe;
        int v = edges[e].v;
        if (edges[e].cap > EPS && levelArr[v] == levelArr[u] + 1) {
            double ret = dfs(v, t, f < edges[e].cap ? f : edges[e].cap);
            if (ret > EPS) {
                edges[e].cap -= ret;
                edges[e ^ 1].cap += ret;
                return ret;
            }
        }
    }
    return 0.0;
}

double dinic(int s, int t) {
    levelArr = (int *)malloc(sizeof(int) * nodeCnt);
    itArr = (int *)malloc(sizeof(int) * nodeCnt);
    queueArr = (int *)malloc(sizeof(int) * nodeCnt);

    double flow = 0.0;
    while (bfs(s, t)) {
        for (int i = 0; i < nodeCnt; i++) itArr[i] = head[i];
        while (1) {
            double f = dfs(s, t, INF);
            if (f <= EPS) break;
            flow += f;
        }
    }

    free(levelArr);
    free(itArr);
    free(queueArr);
    return flow;
}

int main() {
    int n, m;
    /*
      Assumed input format:
      n m
      sx sy
      tx ty
      n lines: x1 y1 x2 y2   (pipe segments)
      m lines: x y           (stop valves)

      Output:
      minimal total pipe length to cut off water from source to repair point,
      or -1 if impossible.

      Model:
      - Pipe network is an undirected graph from segments.
      - Valves are vertices where cutting is allowed with zero cost.
      - Cutting a pipe segment costs its geometric length.
      - We seek minimum s-t cut.
      - If source and target are disconnected already => 0.
      - If impossible (e.g. same point and no way to separate) => -1.
    */

    if (scanf("%d %d", &n, &m) != 2) return 0;

    Point S, T;
    scanf("%lf %lf", &S.x, &S.y);
    scanf("%lf %lf", &T.x, &T.y);

    Point *a = (Point *)malloc(sizeof(Point) * n);
    Point *b = (Point *)malloc(sizeof(Point) * n);
    Point *valves = (Point *)malloc(sizeof(Point) * m);

    int sid = get_point_id(S);
    int tid = get_point_id(T);

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf %lf", &a[i].x, &a[i].y, &b[i].x, &b[i].y);
        get_point_id(a[i]);
        get_point_id(b[i]);
    }
    for (int i = 0; i < m; i++) {
        scanf("%lf %lf", &valves[i].x, &valves[i].y);
        get_point_id(valves[i]);
    }

    sid = get_point_id(S);
    tid = get_point_id(T);

    if (sid == tid) {
        printf("-1\n");
        free(a); free(b); free(valves); free(pts);
        return 0;
    }

    int N = pcount;
    init_graph(N, 4 * n + 10);

    for (int i = 0; i < n; i++) {
        int u = get_point_id(a[i]);
        int v = get_point_id(b[i]);
        double w = dist_pt(a[i], b[i]);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }

    double ans = dinic(sid, tid);

    if (ans >= INF / 2) printf("-1\n");
    else {
        if (fabs(ans - round(ans)) < 1e-6) printf("%.0f\n", ans);
        else printf("%.10f\n", ans);
    }

    free(a);
    free(b);
    free(valves);
    free(pts);
    free(edges);
    free(head);
    return 0;
}

