    }

    // Remove duplicate points (within tolerance)
    const double EPS = 1e-9;
    vector<Point> uniquePoints;
    for (auto &pt : points) {
        bool dup = false;
        for (auto &up : uniquePoints) {
            if (fabs(up.x - pt.x) < EPS && fabs(up.y - pt.y) < EPS) {
                dup = true;
                break;
            }
        }
        if (!dup) uniquePoints.push_back(pt);
    }

    int V = uniquePoints.size();
    int srcIdx = -1, repairIdx = -1;
    for (int i = 0; i < V; i++) {
        if (fabs(uniquePoints[i].x - source.x) < EPS && fabs(uniquePoints[i].y - source.y) < EPS)
            srcIdx = i;
        if (fabs(uniquePoints[i].x - repair.x) < EPS && fabs(uniquePoints[i].y - repair.y) < EPS)
            repairIdx = i;
    }

    if (srcIdx == repairIdx) {
        cout << 0 << "\n";
        return 0;
    }

    // Build adjacency list
    vector<vector<pair<int,double>>> adj(V);

    // Add edges for pipe segments
    for (auto &p : pipes) {
        int u = -1, v = -1;
        for (int i = 0; i < V; i++) {
            if (fabs(uniquePoints[i].x - p.first.x) < EPS && fabs(uniquePoints[i].y - p.first.y) < EPS)
                u = i;
            if (fabs(uniquePoints[i].x - p.second.x) < EPS && fabs(uniquePoints[i].y - p.second.y) < EPS)
                v = i;
        }
        double d = dist(p.first, p.second);
        adj[u].push_back({v, d});
        adj[v].push_back({u, d});
    }

    // Add edges for stop valves: each valve connects its nearest two pipe endpoints? 
    // Actually, a stop valve is just a point on the pipe network; it doesn't add new connections.
    // So we skip them for edges.

    // Dijkstra
    vector<double> distTo(V, 1e18);
    distTo[srcIdx] = 0;
    priority_queue<pair<double,int>, vector<pair<double,int>>, greater<pair<double,int>>> pq;
    pq.push({0, srcIdx});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > distTo[u] + EPS) continue;
        for (auto &[v, w] : adj[u]) {
            if (distTo[v] > distTo[u] + w + EPS) {
                distTo[v] = distTo[u] + w;
                pq.push({distTo[v], v});
            }
        }
    }

    if (distTo[repairIdx] > 1e17) {
        cout << -1 << "\n";
    } else {
        cout << fixed << setprecision(10) << distTo[repairIdx] << "\n";
    }

    return 0;
}

