using namespace std;

/*
Because the original statement available here is truncated, this solution implements
the standard geometric interpretation of the task:

- Pipe network consists of line segments.
- There is one source point S and one repairing point T.
- Some points are stop valves; closing a valve blocks water flow through that point.
- We need the minimum total length of pipe segments that must be "stopped" so that
  water from S cannot reach T.
- If S and T are already disconnected, answer is 0.
- If it is impossible to stop the supply, answer is -1.

Model:
Build an undirected geometric graph from all segment endpoints, all valve points, S, T,
and all intersections between segments / points lying on segments. Each original pipe
segment is split into elementary edges; each such edge has capacity = its geometric length
(the cost to stop that piece of pipe). A valve point is modeled by splitting the vertex
into vin -> vout with capacity 0 if it is a valve, otherwise INF; all incident edges
connect through this split, so cutting at a valve costs 0.

Then the answer is the minimum s-t cut in this graph.

Input format assumed:
n m
x1 y1 x2 y2           (n lines: pipe segments)
...
vx vy                 (m lines: stop valves)
sx sy
tx ty

If your judge uses a different exact format, only the parsing part may need adjustment.

All coordinates are read as doubles. Geometry is handled robustly with EPS and point
deduplication by coordinates generated from input/intersections only.
*/

static const double EPS = 1e-9;
static const double INF = 1e100;

int sgn(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

struct Point {
    double x, y;
};

bool samePoint(const Point& a, const Point& b) {
    return fabs(a.x - b.x) < 1e-8 && fabs(a.y - b.y) < 1e-8;
}

double distPt(const Point& a, const Point& b) {
    return hypot(a.x - b.x, a.y - b.y);
}

Point operator+(const Point& a, const Point& b) { return {a.x + b.x, a.y + b.y}; }
Point operator-(const Point& a, const Point& b) { return {a.x - b.x, a.y - b.y}; }
Point operator*(const Point& a, double k) { return {a.x * k, a.y * k}; }

double cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }
double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }

bool onSegment(const Point& p, const Point& a, const Point& b) {
    return sgn(cross(b - a, p - a)) == 0 && sgn(dot(p - a, p - b)) <= 0;
}

struct Segment {
    Point a, b;
};

bool segmentIntersection(const Segment& s1, const Segment& s2, vector<Point>& out) {
    Point a = s1.a, b = s1.b, c = s2.a, d = s2.b;
    Point r = b - a, s = d - c;
    double rxs = cross(r, s);
    double qpxr = cross(c - a, r);

    if (fabs(rxs) < EPS && fabs(qpxr) < EPS) {
        // Collinear: add overlapping endpoints that lie on the other segment.
        vector<Point> cand;
        if (onSegment(a, c, d)) cand.push_back(a);
        if (onSegment(b, c, d)) cand.push_back(b);
        if (onSegment(c, a, b)) cand.push_back(c);
        if (onSegment(d, a, b)) cand.push_back(d);
        for (auto &p : cand) {
            bool ok = true;
            for (auto &q : out) if (samePoint(p, q)) ok = false;
            if (ok) out.push_back(p);
        }
        return !cand.empty();
    }
    if (fabs(rxs) < EPS) return false;

    double t = cross(c - a, s) / rxs;
    double u = cross(c - a, r) / rxs;
    if (t > -EPS && t < 1 + EPS && u > -EPS && u < 1 + EPS) {
        Point p = a + r * t;
        out.push_back(p);
        return true;
    }
    return false;
}

struct Dinic {
    struct Edge {
        int to, rev;
        double cap;
    };
    int n;
    vector<vector<Edge>> g;
    vector<int> level, it;

    Dinic(int n = 0): n(n), g(n), level(n), it(n) {}

    void addEdge(int fr, int to, double cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{fr, (int)g[fr].size(), 0};
        g[fr].push_back(a);
        g[to].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : g[v]) {
                if (e.cap > EPS && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    double dfs(int v, int t, double f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > EPS && level[v] < level[e.to]) {
                double d = dfs(e.to, t, min(f, e.cap));
                if (d > EPS) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    double maxflow(int s, int t) {
        double flow = 0;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (true) {
                double f = dfs(s, t, INF);
                if (f <= EPS) break;
                flow += f;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<Segment> segs(n);
    for (int i = 0; i < n; ++i) {
        cin >> segs[i].a.x >> segs[i].a.y >> segs[i].b.x >> segs[i].b.y;
    }

    vector<Point> valves(m);
    for (int i = 0; i < m; ++i) cin >> valves[i].x >> valves[i].y;

    Point S, T;
    cin >> S.x >> S.y;
    cin >> T.x >> T.y;

    // Collect split points for each segment.
    vector<vector<Point>> ptsOnSeg(n);
    for (int i = 0; i < n; ++i) {
        ptsOnSeg[i].push_back(segs[i].a);
        ptsOnSeg[i].push_back(segs[i].b);
    }

    // Add intersections between segments.
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            vector<Point> inter;
            segmentIntersection(segs[i], segs[j], inter);
            for (auto &p : inter) {
                ptsOnSeg[i].push_back(p);
                ptsOnSeg[j].push_back(p);
            }
        }
    }

    // Add valves, S, T if they lie on segments.
    auto addPointIfOnSegments = [&](const Point& p) {
        for (int i = 0; i < n; ++i) {
            if (onSegment(p, segs[i].a, segs[i].b)) ptsOnSeg[i].push_back(p);
        }
    };
    for (auto &v : valves) addPointIfOnSegments(v);
    addPointIfOnSegments(S);
    addPointIfOnSegments(T);

    // Global unique points.
    vector<Point> allPts;
    auto getPointId = [&](const Point& p) {
        for (int i = 0; i < (int)allPts.size(); ++i) {
            if (samePoint(allPts[i], p)) return i;
        }
        allPts.push_back(p);
        return (int)allPts.size() - 1;
    };

    // For each segment, dedup and sort points along it, then create elementary edges.
    struct ESeg { int u, v; double w; };
    vector<ESeg> edges;

    for (int i = 0; i < n; ++i) {
        auto &vec = ptsOnSeg[i];
        vector<Point> uniq;
        for (auto &p : vec) {
            bool ok = true;
            for (auto &q : uniq) if (samePoint(p, q)) { ok = false; break; }
            if (ok) uniq.push_back(p);
        }

        Point a = segs[i].a, b = segs[i].b;
        Point d = b - a;
        vector<pair<double, Point>> ord;
        for (auto &p : uniq) {
            double t = (fabs(d.x) >= fabs(d.y)) ? ((fabs(d.x) < EPS) ? 0 : (p.x - a.x) / d.x)
                                                : ((fabs(d.y) < EPS) ? 0 : (p.y - a.y) / d.y);
            ord.push_back({t, p});
        }
        sort(ord.begin(), ord.end(), [&](auto &L, auto &R) { return L.first < R.first; });

        for (int j = 0; j + 1 < (int)ord.size(); ++j) {
            Point p = ord[j].second, q = ord[j + 1].second;
            double w = distPt(p, q);
            if (w <= EPS) continue;
            int u = getPointId(p);
            int v = getPointId(q);
            edges.push_back({u, v, w});
        }
    }

    int sId = getPointId(S);
    int tId = getPointId(T);

    // Check S and T are actually on the network.
    bool sOn = false, tOn = false;
    for (int i = 0; i < n; ++i) {
        if (onSegment(S, segs[i].a, segs[i].b)) sOn = true;
        if (onSegment(T, segs[i].a, segs[i].b)) tOn = true;
    }
    if (!sOn || !tOn) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> isValve(allPts.size(), 0);
    for (int i = 0; i < (int)allPts.size(); ++i) {
        for (auto &v : valves) if (samePoint(allPts[i], v)) isValve[i] = 1;
    }

    // Source and target points themselves cannot be removed by valve closure in min-cut formulation.
    isValve[sId] = 0;
    isValve[tId] = 0;

    int V = allPts.size();
    auto IN = [&](int x) { return 2 * x; };
    auto OUT = [&](int x) { return 2 * x + 1; };

    Dinic din(2 * V);

    for (int i = 0; i < V; ++i) {
        din.addEdge(IN(i), OUT(i), isValve[i] ? 0.0 : INF);
    }

    for (auto &e : edges) {
        din.addEdge(OUT(e.u), IN(e.v), e.w);
        din.addEdge(OUT(e.v), IN(e.u), e.w);
    }

    double ans = din.maxflow(OUT(sId), IN(tId));

    if (ans > INF / 2) {
        cout << -1 << '\n';
    } else {
        // If disconnected already, maxflow = 0.
        cout.setf(ios::fixed);
        cout << setprecision(10) << ans + 1e-10 << '\n';
    }

    return 0;
}

import sys
import math
from collections import deque, defaultdict

EPS = 1e-9
INF = 10**100


def feq(a, b):
    return abs(a - b) <= EPS


def point_eq(p, q):
    return feq(p[0], q[0]) and feq(p[1], q[1])


def cross(ax, ay, bx, by):
    return ax * by - ay * bx


def dot(ax, ay, bx, by):
    return ax * bx + ay * by


def on_segment(p, a, b):
    px, py = p
    ax, ay = a
    bx, by = b
    if abs(cross(bx - ax, by - ay, px - ax, py - ay)) > EPS:
        return False
    return (
        min(ax, bx) - EPS <= px <= max(ax, bx) + EPS and
        min(ay, by) - EPS <= py <= max(ay, by) + EPS
    )


def seg_intersection(a, b, c, d):
    ax, ay = a
    bx, by = b
    cx, cy = c
    dx, dy = d

    r_x, r_y = bx - ax, by - ay
    s_x, s_y = dx - cx, dy - cy

    rxs = cross(r_x, r_y, s_x, s_y)
    qpx, qpy = cx - ax, cy - ay
    qpxr = cross(qpx, qpy, r_x, r_y)

    # Collinear
    if abs(rxs) <= EPS and abs(qpxr) <= EPS:
        rr = dot(r_x, r_y, r_x, r_y)
        if rr <= EPS:
            if point_eq(a, c):
                return [a]
            return []
        t0 = dot(cx - ax, cy - ay, r_x, r_y) / rr
        t1 = dot(dx - ax, dy - ay, r_x, r_y) / rr
        lo = max(0.0, min(t0, t1))
        hi = min(1.0, max(t0, t1))
        if lo > hi + EPS:
            return []
        if abs(lo - hi) <= EPS:
            return [(ax + lo * r_x, ay + lo * r_y)]
        # overlapping segment; return endpoints of overlap
        p1 = (ax + lo * r_x, ay + lo * r_y)
        p2 = (ax + hi * r_x, ay + hi * r_y)
        return [p1, p2]

    # Parallel non-intersecting
    if abs(rxs) <= EPS:
        return []

    t = cross(qpx, qpy, s_x, s_y) / rxs
    u = cross(qpx, qpy, r_x, r_y) / rxs
    if -EPS <= t <= 1 + EPS and -EPS <= u <= 1 + EPS:
        return [(ax + t * r_x, ay + t * r_y)]
    return []


def dist(p, q):
    return math.hypot(p[0] - q[0], p[1] - q[1])


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, u, v, c):
        self.g[u].append([v, c, len(self.g[v])])
        self.g[v].append([u, 0.0, len(self.g[u]) - 1])

    def maxflow(self, s, t):
        flow = 0.0
        n = self.n
        while True:
            level = [-1] * n
            q = deque([s])
            level[s] = 0
            while q:
                u = q.popleft()
                for v, c, rev in self.g[u]:
                    if c > EPS and level[v] < 0:
                        level[v] = level[u] + 1
                        q.append(v)
            if level[t] < 0:
                break

            it = [0] * n

            def dfs(u, f):
                if u == t:
                    return f
                for i in range(it[u], len(self.g[u])):
                    it[u] = i
                    v, c, rev = self.g[u][i]
                    if c > EPS and level[u] + 1 == level[v]:
                        ret = dfs(v, min(f, c))
                        if ret > EPS:
                            self.g[u][i][1] -= ret
                            self.g[v][rev][1] += ret
                            return ret
                return 0.0

            while True:
                pushed = dfs(s, INF)
                if pushed <= EPS:
                    break
                flow += pushed
        return flow


