        Point start, end;
        double length;
        List<Double> valvePositions; // positions along the pipe from start
        int id;

        Pipe(Point start, Point end, int id) {
            this.start = start;
            this.end = end;
            this.length = dist(start, end);
            this.valvePositions = new ArrayList<>();
            this.id = id;
        }

        static double dist(Point a, Point b) {
            return Math.sqrt((a.x-b.x)*(a.x-b.x) + (a.y-b.y)*(a.y-b.y));
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read number of pipe segments
        int N = Integer.parseInt(br.readLine().trim());
        List<Pipe> pipes = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            String[] coords = br.readLine().trim().split(" ");
