            double y1 = Double.parseDouble(coords[1]);
            double x2 = Double.parseDouble(coords[2]);
            double y2 = Double.parseDouble(coords[3]);
            pipes.add(new Pipe(new Point(x1, y1), new Point(x2, y2), i));
        }

        // Read number of stop valves
        int M = Integer.parseInt(br.readLine().trim());
        for (int i = 0; i < M; i++) {
            String[] valveData = br.readLine().trim().split(" ");
            int pipeIdx = Integer.parseInt(valveData[0]);
            double x = Double.parseDouble(valveData[1]);
            double y = Double.parseDouble(valveData[2]);

            Pipe pipe = pipes.get(pipeIdx);
            double pos = Pipe.dist(pipe.start, new Point(x, y));
            pipe.valvePositions.add(pos);
        }

        // Read source point
        String[] srcData = br.readLine().trim().split(" ");
        Point source = new Point(Double.parseDouble(srcData[0]), Double.parseDouble(srcData[1]));

        // Read repairing point
        String[] repairData = br.readLine().trim().split(" ");
        Point repair = new Point(Double.parseDouble(repairData[0]), Double.parseDouble(repairData[1]));

        // For each pipe, sort valve positions
        for (Pipe p : pipes) {
            Collections.sort(p.valvePositions);
        }

        // Build graph: each pipe segment is split into sub-segments by valves
        // Nodes are: source, repair, and connection points (endpoints and valves)
        // We need to find which pipes/valves the source and repair points lie on

        int sourcePipe = -1;
        int repairPipe = -1;

        for (int i = 0; i < N; i++) {
            Pipe p = pipes.get(i);
            if (pointOnSegment(source, p.start, p.end)) {
                sourcePipe = i;
            }
            if (pointOnSegment(repair, p.start, p.end)) {
                repairPipe = i;
            }
        }

        if (sourcePipe == -1 || repairPipe == -1) {
            System.out.println(-1);
            return;
        }

        if (sourcePipe == repairPipe) {
            // Source and repair on same pipe
            Pipe p = pipes.get(sourcePipe);
            double srcPos = Pipe.dist(p.start, source);
            double repPos = Pipe.dist(p.start, repair);

            // Find the minimal length to cut between them
            // We need to find valves between source and repair
            double minLen = p.length;
            double startPos = Math.min(srcPos, repPos);
            double endPos = Math.max(srcPos, repPos);

            // We can cut at valves or at the source/repair points themselves
            List<Double> relevantValves = new ArrayList<>();
            for (double v : p.valvePositions) {
                if (v > startPos && v < endPos) {
                    relevantValves.add(v);
                }
            }

            if (relevantValves.isEmpty()) {
                // No valves between, need to cut the entire segment
                minLen = endPos - startPos;
            } else {
                // Find minimal sub-segment that can be cut
                double prev = startPos;
                for (double v : relevantValves) {
                    minLen = Math.min(minLen, v - prev);
                    prev = v;
                }
                minLen = Math.min(minLen, endPos - prev);
            }

            System.out.printf("%.2f%n", minLen);
            return;
        }

        // For different pipes, we need to find paths in the pipe network
        // Build adjacency between pipes at shared endpoints
        Map<String, List<int[]>> endpointMap = new HashMap<>(); // "x,y" -> list of (pipeId, isStart)

        for (int i = 0; i < N; i++) {
            Pipe p = pipes.get(i);
            String key1 = p.start.x + "," + p.start.y;
            String key2 = p.end.x + "," + p.end.y;

            endpointMap.computeIfAbsent(key1, k -> new ArrayList<>()).add(new int[]{i, 1});
            endpointMap.computeIfAbsent(key2, k -> new ArrayList<>()).add(new int[]{i, 0});
        }

        // Build graph where each pipe can be traversed, and cost is the minimum cut within that pipe
        // Use Dijkstra-like approach to find minimum cut from source to repair

        // For each pipe, we need to consider the minimum cost to go from one end to the other
        // considering valves that can cut the pipe

        // State: (pipeId, position along pipe from start)
        // We'll simplify by considering only endpoints and valve positions as nodes

        // Build a graph of all important points
        Map<String, Integer> pointToId = new HashMap<>();
        List<Point> allPoints = new ArrayList<>();

        // Add pipe endpoints
        for (int i = 0; i < N; i++) {
            Pipe p = pipes.get(i);
            String key1 = p.start.x + "," + p.start.y;
            String key2 = p.end.x + "," + p.end.y;
            if (!pointToId.containsKey(key1)) {
                pointToId.put(key1, allPoints.size());
                allPoints.add(p.start);
            }
            if (!pointToId.containsKey(key2)) {
                pointToId.put(key2, allPoints.size());
                allPoints.add(p.end);
            }
        }

        // Add source and repair
        String srcKey = source.x + "," + source.y;
        String repKey = repair.x + "," + repair.y;
        if (!pointToId.containsKey(srcKey)) {
            pointToId.put(srcKey, allPoints.size());
            allPoints.add(source);
        }
        if (!pointToId.containsKey(repKey)) {
            pointToId.put(repKey, allPoints.size());
            allPoints.add(repair);
        }

        int V = allPoints.size();
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < V; i++) {
            graph.add(new ArrayList<>());
        }

        // For each pipe, add edges between consecutive important points on that pipe
        for (int i = 0; i < N; i++) {
            Pipe p = pipes.get(i);

            // Collect all important points on this pipe
            List<Double> positions = new ArrayList<>();
            List<Integer> pointIds = new ArrayList<>();

            // Add endpoints
            positions.add(0.0);
            pointIds.add(pointToId.get(p.start.x + "," + p.start.y));
            positions.add(p.length);
            pointIds.add(pointToId.get(p.end.x + "," + p.end.y));

            // Add valve positions
            for (double pos : p.valvePositions) {
                positions.add(pos);
                // Create a point for this valve position
                double ratio = pos / p.length;
                double vx = p.start.x + ratio * (p.end.x - p.start.x);
                double vy = p.start.y + ratio * (p.end.y - p.start.y);
                String key = vx + "," + vy;
                if (!pointToId.containsKey(key)) {
                    pointToId.put(key, allPoints.size());
                    allPoints.add(new Point(vx, vy));
                }
                pointIds.add(pointToId.get(key));
            }

            // Add source and repair if on this pipe
            if (sourcePipe == i) {
                double pos = Pipe.dist(p.start, source);
                positions.add(pos);
                pointIds.add(pointToId.get(srcKey));
            }
            if (repairPipe == i) {
                double pos = Pipe.dist(p.start, repair);
                positions.add(pos);
                pointIds.add(pointToId.get(repKey));
            }

            // Sort by position
            Integer[] indices = new Integer[positions.size()];
            for (int j = 0; j < indices.length; j++) indices[j] = j;
            Arrays.sort(indices, (a, b) -> Double.compare(positions.get(a), positions.get(b)));

            // Add edges between consecutive points
            for (int j = 0; j < indices.length - 1; j++) {
                int idx1 = indices[j];
                int idx2 = indices[j+1];
                int u = pointIds.get(idx1);
                int v = pointIds.get(idx2);
                double dist = positions.get(idx2) - positions.get(idx1);
                graph.get(u).add(new Edge(v, dist));
                graph.get(v).add(new Edge(u, dist));
            }
        }

        // Now run Dijkstra from source to repair
        int srcId = pointToId.get(srcKey);
        int repId = pointToId.get(repKey);

        double[] dist = new double[V];
        Arrays.fill(dist, Double.MAX_VALUE);
        dist[srcId] = 0;

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> Double.compare(a.dist, b.dist));
        pq.add(new Node(srcId, 0));

        while (!pq.isEmpty()) {
            Node curr = pq.poll();
            int u = curr.id;
            if (curr.dist > dist[u]) continue;
            if (u == repId) break;

            for (Edge e : graph.get(u)) {
                double newDist = dist[u] + e.weight;
                if (newDist < dist[e.to]) {
                    dist[e.to] = newDist;
                    pq.add(new Node(e.to, newDist));
                }
            }
        }

        if (dist[repId] == Double.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.printf("%.2f%n", dist[repId]);
        }
    }

    static class Edge {
        int to;
        double weight;
        Edge(int to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class Node {
        int id;
        double dist;
        Node(int id, double dist) {
            this.id = id;
            this.dist = dist;
        }
    }

    static boolean pointOnSegment(Point p, Point a, Point b) {
        double cross = (p.y - a.y) * (b.x - a.x) - (p.x - a.x) * (b.y - a.y);
        if (Math.abs(cross) > 1e-9) return false;

        double dot = (p.x - a.x) * (b.x - a.x) + (p.y - a.y) * (b.y - a.y);
        if (dot < 0) return false;

        double squaredLen = (b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y);
        if (dot > squaredLen) return false;

        return true;
    }
}

