  * collinear overlapping segments are merged by split points at endpoints lying on each other; overlapping interiors are hard.
Competitive problems of this type usually avoid overlaps. We assume no overlapping collinear interiors.

Use exact rational-ish comparisons with doubles and EPS.
Deduplicate points by rounded coordinates key.
*/

public class Main {
    static final double EPS = 1e-9;
    static final double INF = 1e100;

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner(InputStream is) { br = new BufferedReader(new InputStreamReader(is)); }
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }

    static class Point {
        double x, y;
        int id;
        boolean valve;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static class Seg {
        Point a, b;
        Seg(Point a, Point b) { this.a = a; this.b = b; }
    }

    static class EdgeKey {
        int u, v;
        EdgeKey(int a, int b) {
            if (a < b) { u = a; v = b; }
            else { u = b; v = a; }
        }
        public boolean equals(Object o) {
            if (!(o instanceof EdgeKey)) return false;
            EdgeKey e = (EdgeKey) o;
            return u == e.u && v == e.v;
        }
        public int hashCode() { return u * 1000003 + v; }
    }

    static double cross(double ax, double ay, double bx, double by) { return ax * by - ay * bx; }
    static double cross(Point a, Point b, Point c) { return cross(b.x - a.x, b.y - a.y, c.x - a.x, c.y - a.y); }
    static double dot(Point a, Point b, Point c) { return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y); }
    static double dist(Point a, Point b) { return Math.hypot(a.x - b.x, a.y - b.y); }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.abs(cross(a, b, p)) < EPS &&
                Math.min(a.x, b.x) - EPS <= p.x && p.x <= Math.max(a.x, b.x) + EPS &&
                Math.min(a.y, b.y) - EPS <= p.y && p.y <= Math.max(a.y, b.y) + EPS;
    }

    static Point lineIntersection(Point a, Point b, Point c, Point d) {
        double A1 = b.y - a.y, B1 = a.x - b.x, C1 = A1 * a.x + B1 * a.y;
        double A2 = d.y - c.y, B2 = c.x - d.x, C2 = A2 * c.x + B2 * c.y;
        double det = A1 * B2 - A2 * B1;
        if (Math.abs(det) < EPS) return null;
        double x = (B2 * C1 - B1 * C2) / det;
        double y = (A1 * C2 - A2 * C1) / det;
        return new Point(x, y);
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double c1 = cross(a, b, c), c2 = cross(a, b, d);
        double c3 = cross(c, d, a), c4 = cross(c, d, b);
        if (((c1 > EPS && c2 < -EPS) || (c1 < -EPS && c2 > EPS)) &&
            ((c3 > EPS && c4 < -EPS) || (c3 < -EPS && c4 > EPS))) return true;
        return onSegment(a, b, c) || onSegment(a, b, d) || onSegment(c, d, a) || onSegment(c, d, b);
    }

    static String key(double x, double y) {
        long xx = Math.round(x * 1e8);
        long yy = Math.round(y * 1e8);
        return xx + "#" + yy;
    }

    static Point getPoint(Map<String, Point> map, List<Point> pts, double x, double y) {
        String k = key(x, y);
        Point p = map.get(k);
        if (p == null) {
            p = new Point(x, y);
            p.id = pts.size();
            pts.add(p);
            map.put(k, p);
        }
        return p;
    }

    // Dinic
    static class Dinic {
        static class E {
            int to, rev;
            double cap;
            E(int to, int rev, double cap) { this.to = to; this.rev = rev; this.cap = cap; }
        }
        List<E>[] g;
        int[] level, it;
        Dinic(int n) {
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }
        void addEdge(int s, int t, double cap) {
            E a = new E(t, g[t].size(), cap);
            E b = new E(s, g[s].size(), 0);
            g[s].add(a); g[t].add(b);
        }
        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (E e : g[v]) if (e.cap > EPS && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.add(e.to);
                }
            }
            return level[t] >= 0;
        }
        double dfs(int v, int t, double f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                E e = g[v].get(it[v]);
                if (e.cap > EPS && level[v] + 1 == level[e.to]) {
                    double ret = dfs(e.to, t, Math.min(f, e.cap));
                    if (ret > EPS) {
                        e.cap -= ret;
                        g[e.to].get(e.rev).cap += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }
        double maxFlow(int s, int t) {
            double flow = 0, inf = 1e100;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                while (true) {
                    double f = dfs(s, t, inf);
                    if (f <= EPS) break;
                    flow += f;
                }
            }
            return flow;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);   // number of pipe segments
        int m = fs.nextInt();              // number of valves

        Map<String, Point> pointMap = new HashMap<>();
        List<Point> points = new ArrayList<>();
        List<Seg> segs = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            double x1 = fs.nextDouble(), y1 = fs.nextDouble();
            double x2 = fs.nextDouble(), y2 = fs.nextDouble();
            Point a = getPoint(pointMap, points, x1, y1);
            Point b = getPoint(pointMap, points, x2, y2);
            segs.add(new Seg(a, b));
        }

        for (int i = 0; i < m; i++) {
            double x = fs.nextDouble(), y = fs.nextDouble();
            Point p = getPoint(pointMap, points, x, y);
            p.valve = true;
        }

        double sx = fs.nextDouble(), sy = fs.nextDouble();
        double tx = fs.nextDouble(), ty = fs.nextDouble();
        Point source = getPoint(pointMap, points, sx, sy);
        Point repair = getPoint(pointMap, points, tx, ty);

        if (source.valve || repair.valve) {
            System.out.println("0");
            return;
        }

        List<List<Point>> splitPts = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Point> lst = new ArrayList<>();
            lst.add(segs.get(i).a);
            lst.add(segs.get(i).b);
            splitPts.add(lst);
        }

        for (Point p : points) {
            for (int i = 0; i < n; i++) {
                Seg s = segs.get(i);
                if (onSegment(s.a, s.b, p)) splitPts.get(i).add(p);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                Seg s1 = segs.get(i), s2 = segs.get(j);
                if (!segmentsIntersect(s1.a, s1.b, s2.a, s2.b)) continue;
                Point inter = lineIntersection(s1.a, s1.b, s2.a, s2.b);
                if (inter != null && onSegment(s1.a, s1.b, inter) && onSegment(s2.a, s2.b, inter)) {
                    Point p = getPoint(pointMap, points, inter.x, inter.y);
                    splitPts.get(i).add(p);
                    splitPts.get(j).add(p);
                } else {
                    // collinear/shared-endpoint cases: existing points already added by onSegment loop
                }
            }
        }

        Map<EdgeKey, Double> edgeMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            Seg s = segs.get(i);
            List<Point> lst = splitPts.get(i);
            double dx = s.b.x - s.a.x, dy = s.b.y - s.a.y;
            double len2 = dx * dx + dy * dy;
            lst.sort(Comparator.comparingDouble(p -> ((p.x - s.a.x) * dx + (p.y - s.a.y) * dy) / len2));
            List<Point> uniq = new ArrayList<>();
            for (Point p : lst) {
                if (uniq.isEmpty() || dist(uniq.get(uniq.size() - 1), p) > 1e-8) uniq.add(p);
            }
            for (int k = 0; k + 1 < uniq.size(); k++) {
                Point u = uniq.get(k), v = uniq.get(k + 1);
                double w = dist(u, v);
                if (w <= EPS) continue;
                if (u.valve || v.valve) continue; // deleted by free valve closure
                EdgeKey ek = new EdgeKey(u.id, v.id);
                edgeMap.put(ek, edgeMap.getOrDefault(ek, 0.0) + w);
            }
        }

        int V = points.size();
        List<int[]> adj = new ArrayList<>();
        for (Map.Entry<EdgeKey, Double> e : edgeMap.entrySet()) {
            adj.add(new int[]{e.getKey().u, e.getKey().v});
        }

        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < V; i++) g.add(new ArrayList<>());
        for (int[] e : adj) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }

        boolean[] vis = new boolean[V];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(source.id);
        vis[source.id] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (!vis[v]) {
                vis[v] = true;
                q.add(v);
            }
        }

        if (!vis[repair.id]) {
            System.out.println("0");
            return;
        }

        int[] mapId = new int[V];
        Arrays.fill(mapId, -1);
        int cnt = 0;
        for (int i = 0; i < V; i++) if (vis[i]) mapId[i] = cnt++;

        Dinic dinic = new Dinic(cnt);
        for (Map.Entry<EdgeKey, Double> e : edgeMap.entrySet()) {
            int u = e.getKey().u, v = e.getKey().v;
            if (!vis[u] || !vis[v]) continue;
            double w = e.getValue();
            int a = mapId[u], b = mapId[v];
            dinic.addEdge(a, b, w);
            dinic.addEdge(b, a, w);
        }

        double ans = dinic.maxFlow(mapId[source.id], mapId[repair.id]);
        if (ans > 5e99) System.out.println("-1");
        else {
            if (Math.abs(ans - Math.round(ans)) < 1e-6) System.out.println((long)Math.round(ans));
            else System.out.printf(Locale.US, "%.10f%n", ans);
        }
    }
}
